import { computeTotal, subtotalOf, TAX_RATE } from './checkout.js';
import { shippingCost } from './shipping.js';
import { roundCents } from './format.js';

// checkoutSummary is the single entry point the storefront calls for an order overview.
export function checkoutSummary(items, options = {}) {
  const subtotal = subtotalOf(items);
  const taxRate = options.taxRate ?? TAX_RATE;
  const tax = roundCents(subtotal * taxRate);
  const shipping = shippingCost(subtotal);
  const grandTotal = roundCents(subtotal + tax + shipping);
  return { subtotal, tax, shipping, grandTotal };
}

